// EmployeeDashboard.jsx - Improved Version with Modern Best Practices
import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Link } from 'react-router-dom'; // For linking to ticket details
import api from "../api/axios"; // Your custom axios instance with interceptors

const EmployeeDashboard = () => {
  const dispatch = useDispatch(); // If needed for logout on auth error
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);

  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!user || !token) {
      setError('Please log in to view your tickets.');
      setLoading(false);
      return;
    }

    const fetchTickets = async () => {
      try {
        const response = await api.get('/tickets/'); // Note: add leading '/' if not in baseURL
        console.log('API Response:', response.data);

        const myTickets = response.data.filter(
          (ticket) => ticket.creator?.id?.toString() === user.id?.toString()
        );

        setTickets(myTickets);
      } catch (err) {
        console.error('Fetch error:', err);
        const message = err.response?.status === 401 
          ? 'Session expired. Please log in again.'
          : 'Failed to load tickets. Please try again.';
        setError(message);

        // Optional: Auto-logout on 401
        if (err.response?.status === 401) {
          dispatch({ type: 'auth/logout' }); // Adjust to your logout action
        }
      } finally {
        setLoading(false);
      }
    };

    fetchTickets();
  }, [token, user, dispatch]);

  // Use title-case statuses as per your project spec
  const statusCounts = {
    Open: tickets.filter(t => t.status === 'Open').length,
    'In Progress': tickets.filter(t => t.status === 'In Progress').length,
    Resolved: tickets.filter(t => t.status === 'Resolved').length,
  };

  const getPriorityColor = (priority) => {
    const p = priority?.toUpperCase() || '';
    if (p.includes('HIGH')) return '#ff4d4f';
    if (p === 'MEDIUM') return '#faad14';
    if (p === 'LOW') return '#52c41a';
    return '#d9d9d9';
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'Open': return '#1890ff';
      case 'In Progress': return '#faad14';
      case 'Resolved': return '#52c41a';
      default: return '#d9d9d9';
    }
  };

  if (loading) {
    return <div style={styles.loading}>Loading your tickets...</div>;
  }

  if (error) {
    return <div style={styles.error}>{error}</div>;
  }

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>My IT Support Tickets</h2>

      {/* Clean, modern count cards */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, borderColor: '#1890ff', background: '#e6f7ff' }}>
          <h3 style={styles.countNumber}>{statusCounts.Open}</h3>
          <p style={styles.countLabel}>Open</p>
        </div>
        <div style={{ ...styles.countCard, borderColor: '#faad14', background: '#fffbe6' }}>
          <h3 style={styles.countNumber}>{statusCounts['In Progress']}</h3>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, borderColor: '#52c41a', background: '#f6ffed' }}>
          <h3 style={styles.countNumber}>{statusCounts.Resolved}</h3>
          <p style={styles.countLabel}>Resolved</p>
        </div>
      </div>

      {/* Ticket cards with links to details */}
      {tickets.length === 0 ? (
        <div style={styles.noTickets}>
          <p>You haven't created any tickets yet.</p>
          <p style={{ marginTop: '8px' }}>
            <Link to="/create-ticket" style={{ color: '#1890ff' }}>Create New Ticket</Link>
          </p>
        </div>
      ) : (
        <div style={styles.ticketsGrid}>
          {tickets.map((ticket) => (
            <Link 
              to={`/tickets/${ticket.id}`} 
              key={ticket.id} 
              style={styles.ticketLink}
            >
              <div style={styles.ticketCard}>
                <div style={styles.ticketHeader}>
                  <h4 style={styles.ticketTitle}>#{ticket.id} - {ticket.title}</h4>
                  <span style={{ ...styles.badge, background: getPriorityColor(ticket.priority) }}>
                    {ticket.priority}
                  </span>
                  <span style={{ ...styles.badge, background: getStatusColor(ticket.status) }}>
                    {ticket.status}
                  </span>
                </div>
                <p style={styles.ticketDescription}>{ticket.description?.substring(0, 150)}...</p>
                <p style={styles.ticketMeta}>
                  Created: {new Date(ticket.created_at).toLocaleDateString()}
                </p>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: '32px',
    maxWidth: '1200px',
    margin: '0 auto',
    background: '#f8f9fa',
    minHeight: '100vh',
  },
  title: {
    fontSize: '28px',
    marginBottom: '32px',
    color: '#1a1a1a',
    fontWeight: '600',
  },
  countsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '20px',
    marginBottom: '40px',
  },
  countCard: {
    padding: '20px',
    borderRadius: '12px',
    border: '2px solid',
    textAlign: 'center',
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
    transition: 'transform 0.2s',
  },
  countNumber: {
    fontSize: '36px',
    margin: '0 0 8px',
    fontWeight: 'bold',
    color: '#1a1a1a',
  },
  countLabel: {
    fontSize: '16px',
    color: '#666',
    margin: 0,
  },
  ticketsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))',
    gap: '24px',
  },
  ticketLink: {
    textDecoration: 'none',
    color: 'inherit',
  },
  ticketCard: {
    padding: '20px',
    borderRadius: '12px',
    background: '#ffffff',
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
    transition: 'transform 0.2s, box-shadow 0.2s',
    cursor: 'pointer',
  },
  ticketHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '12px',
    flexWrap: 'wrap',
    gap: '12px',
  },
  ticketTitle: {
    margin: 0,
    fontSize: '18px',
    fontWeight: '600',
    flex: 1,
    color: '#1a1a1a',
  },
  badge: {
    padding: '6px 12px',
    borderRadius: '20px',
    fontSize: '12px',
    fontWeight: '600',
    color: '#ffffff',
    textTransform: 'uppercase',
  },
  ticketDescription: {
    fontSize: '14px',
    color: '#555',
    margin: '0 0 12px',
    lineHeight: '1.5',
  },
  ticketMeta: {
    fontSize: '12px',
    color: '#888',
    margin: 0,
  },
  loading: {
    textAlign: 'center',
    fontSize: '20px',
    color: '#1890ff',
    padding: '100px 0',
  },
  error: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#ff4d4f',
    padding: '100px 0',
  },
  noTickets: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#666',
    padding: '100px 0',
  },
};

export default EmployeeDashboard;
